const _foAppDefaults=()=>({svAppVersion:"2.6.0",svLastUpdateDate:"",svActive:"-",...coUtil.cofExtKeyState()});window.useFoAppStore=Pinia.defineStore("foApp",{state:_foAppDefaults,actions:{saSetApp(t){if(!t)return;this.svAppVersion=t.appVersion||"2.6.0",this.svLastUpdateDate=t.lastUpdateDate||"",this.svActive=t.active||"-";const s=coUtil.cofExtKeyState(t);Object.keys(s).forEach(e=>{this[e]=s[e]||this[e]||""})},saClear(){Object.assign(this,_foAppDefaults())}}});
